"689 :   private CanInlineResult canInlineReferenceDirectly(
690 :       Node callNode, Node fnNode) {
691 :     if (!isDirectCallNodeReplacementPossible(fnNode)) {
692 :       return CanInlineResult.NO;
693 :     }
694 : 
695 :     Node block = fnNode.getLastChild();
696 : 
697 : 
698 :     // CALL NODE: [ NAME, ARG1, ARG2, ... ]
699 :     Node cArg = callNode.getFirstChild().getNext();
700 : 
701 :     // Functions called via 'call' and 'apply' have a this-object as
702 :     // the first parameter, but this is not part of the called function's
703 :     // parameter list.
704 :     if (!callNode.getFirstChild().isName()) {
705 :       if (NodeUtil.isFunctionObjectCall(callNode)) {
706 :         // TODO(johnlenz): Support replace this with a value.
707 :         if (cArg == null || !cArg.isThis()) {
708 :           return CanInlineResult.NO;
709 :         }
710 :         cArg = cArg.getNext();
711 :       } else {
712 :         // ".apply" call should be filtered before this.
713 :         Preconditions.checkState(!NodeUtil.isFunctionObjectApply(callNode));
714 :       }
715 :     }
716 : 
717 :     // FUNCTION NODE -> LP NODE: [ ARG1, ARG2, ... ]
718 :     Node fnParam = NodeUtil.getFunctionParameters(fnNode).getFirstChild();
719 :     while (cArg != null || fnParam != null) {
720 :       // For each named parameter check if a mutable argument use more than one.
721 :       if (fnParam != null) {
722 :         if (cArg != null) {
723 : 
724 :           // Check for arguments that are evaluated more than once.
725 :           // Note: Unlike block inlining, there it is not possible that a
726 :           // parameter reference will be in a loop.
727 :           if (NodeUtil.mayEffectMutableState(cArg, compiler)
728 :               && NodeUtil.getNameReferenceCount(
729 :                   block, fnParam.getString()) > 1) {
730 :             return CanInlineResult.NO;
731 :           }
732 :         }
733 : 
734 :         // Move to the next name.
735 :         fnParam = fnParam.getNext();
736 :       }
737 : 
738 :       // For every call argument check for side-effects, even if there
739 :       // isn't a named parameter to match.
740 :       if (cArg != null) {
741 :         if (NodeUtil.mayHaveSideEffects(cArg, compiler)) {
742 :           return CanInlineResult.NO;
743 :         }
744 :         cArg = cArg.getNext();
745 :       }
746 :     }
747 : 
748 :     return CanInlineResult.YES;
749 :   }"

"173 :   CanInlineResult canInlineReferenceToFunction(NodeTraversal t,
174 :       Node callNode, Node fnNode, Set<String> needAliases,
175 :       InliningMode mode, boolean referencesThis, boolean containsFunctions) {
176 :     // TODO(johnlenz): This function takes too many parameter, without
177 :     // context.  Modify the API to take a structure describing the function.
178 : 
179 :     // Allow direct function calls or "fn.call" style calls.
180 :     if (!isSupportedCallType(callNode)) {
181 :       return CanInlineResult.NO;
182 :     }
183 : 
184 :     // Limit where functions that contain functions can be inline.  Introducing
185 :     // an inner function into another function can capture a variable and cause
186 :     // a memory leak.  This isn't a problem in the global scope as those values
187 :     // last until explicitly cleared.
188 :     if (containsFunctions) {
189 :       if (!assumeMinimumCapture && !t.inGlobalScope()) {
190 :         // TODO(johnlenz): Allow inlining into any scope without local names or
191 :         // inner functions.
192 :         return CanInlineResult.NO;
193 :       } else if (NodeUtil.isWithinLoop(callNode)) {
194 :         // An inner closure maybe relying on a local value holding a value for a
195 :         // single iteration through a loop.
196 :         return CanInlineResult.NO;
197 :       }
198 :     }
199 : 
200 :     // TODO(johnlenz): Add support for 'apply'
201 :     if (referencesThis && !NodeUtil.isFunctionObjectCall(callNode)) {
202 :       // TODO(johnlenz): Allow 'this' references to be replaced with a
