"245 :   static void maybeAddTempsForCallArguments(
246 :       Node fnNode, Map<String, Node> argMap, Set<String> namesNeedingTemps,
247 :       CodingConvention convention) {
248 :     if (argMap.isEmpty()) {
249 :       // No arguments to check, we are done.
250 :       return;
251 :     }
252 : 
253 :     Preconditions.checkArgument(fnNode.isFunction());
254 :     Node block = fnNode.getLastChild();
255 : 
256 :     Set<String> parameters = argMap.keySet();
257 : 
258 :     // Get the list of parameters that may need temporaries due to
259 :     // side-effects.
260 :     Set<String> namesAfterSideEffects = findParametersReferencedAfterSideEffect(
261 :         parameters, block);
262 : 
263 :     // Check for arguments that are evaluated more than once.
264 :     for (Map.Entry<String, Node> entry : argMap.entrySet()) {
265 :       String argName = entry.getKey();
266 :       if (namesNeedingTemps.contains(argName)) {
267 :         continue;
268 :       }
269 :       Node cArg = entry.getValue();
270 :       boolean safe = true;
271 :       int references = NodeUtil.getNameReferenceCount(block, argName);
272 : 
273 :       if (NodeUtil.mayEffectMutableState(cArg) && references > 0) {
274 :         // Note: Mutable arguments should be assigned to temps, as the
275 :         // may be within in a loop:
276 :         //   function x(a) {
277 :         //     for(var i=0; i<0; i++) {
278 :         //       foo(a);
279 :         //     }
280 :         //   x( [] );
281 :         //
282 :         //   The parameter in the call to foo should not become "[]".
283 :         safe = false;
284 :       } else if (NodeUtil.mayHaveSideEffects(cArg)) {
285 :         // Even if there are no references, we still need to evaluate the
286 :         // expression if it has side-effects.
287 :         safe = false;
288 :       } else if (NodeUtil.canBeSideEffected(cArg)
289 :           && namesAfterSideEffects.contains(argName)) {
290 :         safe = false;
291 :       } else if (references > 1) {
292 :         // Safe is a misnomer, this is a check for "large".
293 :         switch (cArg.getType()) {
294 :           case Token.NAME:
295 :             String name = cArg.getString();
296 :             safe = !(convention.isExported(name));
297 :             break;
298 :           case Token.THIS:
299 :             safe = true;
300 :             break;
301 :           case Token.STRING:
302 :             safe = (cArg.getString().length() < 2);
303 :             break;
304 :           default:
305 :             safe = NodeUtil.isImmutableValue(cArg);
306 :             break;
307 :         }
308 :       }
309 : 
310 :       if (!safe) {
311 :         namesNeedingTemps.add(argName);
312 :       }
313 :     }
314 :   }"

"230 :   private Node aliasAndInlineArguments(
231 :       Node fnTemplateRoot, LinkedHashMap<String, Node> argMap,
232 :       Set<String> namesToAlias) {
233 : 
234 :     if (namesToAlias == null || namesToAlias.isEmpty()) {
235 :       // There are no names to alias, just inline the arguments directly.
236 :       Node result = FunctionArgumentInjector.inject(
237 :           compiler, fnTemplateRoot, null, argMap);
238 :       Preconditions.checkState(result == fnTemplateRoot);
239 :       return result;
240 :     } else {
241 :       // Create local alias of names that can not be safely
242 :       // used directly.
243 : 
244 :       // An arg map that will be updated to contain the
245 :       // safe aliases.
246 :       Map<String, Node> newArgMap = Maps.newHashMap(argMap);
247 : 
248 :       // Declare the alias in the same order as they
249 :       // are declared.
250 :       List<Node> newVars = Lists.newLinkedList();
251 :       // NOTE: argMap is a linked map so we get the parameters in the
252 :       // order that they were declared.
253 :       for (Entry<String, Node> entry : argMap.entrySet()) {
254 :         String name = entry.getKey();
255 :         if (namesToAlias.contains(name)) {
256 :           if (name.equals(THIS_MARKER)) {
257 :             boolean referencesThis = NodeUtil.referencesThis(fnTemplateRoot);
258 :             // Update "this", this is only necessary if "this" is referenced
259 :             // and the value of "this" is not Token.THIS, or the value of "this"
260 :             // has side effects.
261 : 
262 :             Node value = entry.getValue();
263 :             if (!value.isThis()
264 :                 && (referencesThis
265 :                     || NodeUtil.mayHaveSideEffects(value, compiler))) {
266 :               String newName = getUniqueThisName();
267 :               Node newValue = entry.getValue().cloneTree();
268 :               Node newNode = NodeUtil.newVarNode(newName, newValue)
269 :                   .copyInformationFromForTree(newValue);
270 :               newVars.add(0, newNode);
271 :               // Remove the parameter from the list to replace.
272 :               newArgMap.put(THIS_MARKER,
273 :                   IR.name(newName)
274 :                       .srcrefTree(newValue));
275 :             }
276 :           } else {
277 :             Node newValue = entry.getValue().cloneTree();
278 :             Node newNode = NodeUtil.newVarNode(name, newValue)
279 :                 .copyInformationFromForTree(newValue);
280 :             newVars.add(0, newNode);
281 :             // Remove the parameter from the list to replace.
282 :             newArgMap.remove(name);
283 :           }
284 :         }
285 :       }
286 : 
287 :       // Inline the arguments.
288 :       Node result = FunctionArgumentInjector.inject(
289 :           compiler, fnTemplateRoot, null, newArgMap);
290 :       Preconditions.checkState(result == fnTemplateRoot);
291 : 
292 :       // Now that the names have been replaced, add the new aliases for
293 :       // the old names.
294 :       for (Node n : newVars) {
295 :         fnTemplateRoot.addChildToFront(n);
296 :       }
297 : 
298 :       return result;
299 :     }
300 :   }"

