"455 :   private Node inlineFunction(
456 :       Node callNode, Node fnNode, String fnName) {
457 :     Node parent = callNode.getParent();
458 :     Node grandParent = parent.getParent();
459 : 
460 :     // TODO(johnlenz): Consider storing the callSite classification in the
461 :     // reference object and passing it in here.
462 :     CallSiteType callSiteType = classifyCallSite(callNode);
463 :     Preconditions.checkArgument(callSiteType != CallSiteType.UNSUPPORTED);
464 : 
465 :     boolean isCallInLoop = NodeUtil.isWithinLoop(callNode);
466 : 
467 :     // Store the name for the result. This will be used to
468 :     // replace "return expr" statements with "resultName = expr"
469 :     // to replace
470 :     String resultName = null;
471 :     boolean needsDefaultReturnResult = true;
472 :     switch (callSiteType) {
473 :       case SIMPLE_ASSIGNMENT:
474 :         resultName = parent.getFirstChild().getString();
475 :         break;
476 : 
477 :       case VAR_DECL_SIMPLE_ASSIGNMENT:
478 :         resultName = parent.getString();
479 :         break;
480 : 
481 :       case SIMPLE_CALL:
482 :         resultName = null;  // "foo()" doesn't need a result.
483 :         needsDefaultReturnResult = false;
484 :         break;
485 : 
486 :       case EXPRESSION:
487 :         throw new IllegalStateException(
488 :             "Movable expressions must be moved before inlining.");
489 : 
490 :       case DECOMPOSABLE_EXPRESSION:
491 :         throw new IllegalStateException(
492 :             "Decomposable expressions must be decomposed before inlining.");
493 : 
494 :       default:
495 :         throw new IllegalStateException("Unexpected call site type.");
496 :     }
497 : 
498 :     FunctionToBlockMutator mutator = new FunctionToBlockMutator(
499 :         compiler, this.safeNameIdSupplier);
500 : 
501 :     Node newBlock = mutator.mutate(
502 :         fnName, fnNode, callNode, resultName,
503 :         needsDefaultReturnResult, isCallInLoop);
504 : 
505 :     // TODO(nicksantos): Create a common mutation function that
506 :     // can replace either a VAR name assignment, assignment expression or
507 :     // a EXPR_RESULT.
508 :     Node greatGrandParent = grandParent.getParent();
509 :     switch (callSiteType) {
510 :       case VAR_DECL_SIMPLE_ASSIGNMENT:
511 :         // Remove the call from the name node.
512 :         parent.removeChild(parent.getFirstChild());
513 :         Preconditions.checkState(parent.getFirstChild() == null);
514 :         // Add the call, after the VAR.
515 :         greatGrandParent.addChildAfter(newBlock, grandParent);
516 :         break;
517 : 
518 :       case SIMPLE_ASSIGNMENT:
519 :         // The assignment is now part of the inline function so
520 :         // replace it completely.
521 :         Preconditions.checkState(grandParent.isExprResult());
522 :         greatGrandParent.replaceChild(grandParent, newBlock);
523 :         break;
524 : 
525 :       case SIMPLE_CALL:
526 :         // If nothing is looking at the result just replace the call.
527 :         Preconditions.checkState(parent.isExprResult());
528 :         grandParent.replaceChild(parent, newBlock);
529 :         break;
530 : 
531 :       default:
532 :         throw new IllegalStateException("Unexpected call site type.");
533 :     }
534 : 
535 :     return newBlock;
536 :   }"

"610 :   private boolean callMeetsBlockInliningRequirements(
611 :       NodeTraversal t, Node callNode, final Node fnNode,
612 :       Set<String> namesToAlias) {
613 :     final boolean assumeMinimumCapture = this.assumeMinimumCapture;
614 : 
615 :     // Note: functions that contain function definitions are filtered out
616 :     // in isCandidateFunction.
617 : 
618 :     // TODO(johnlenz): Determining if the called function contains VARs
619 :     // or if the caller contains inner functions accounts for 20% of the
620 :     // run-time cost of this pass.
621 : 
622 :     // Don't inline functions with var declarations into a scope with inner
623 :     // functions as the new vars would leak into the inner function and
624 :     // cause memory leaks.
625 :     boolean fnContainsVars = NodeUtil.has(
626 :         NodeUtil.getFunctionBody(fnNode),
627 :         new NodeUtil.MatchDeclaration(),
628 :         new NodeUtil.MatchShallowStatement());
629 :     boolean forbidTemps = false;
630 :     if (!t.inGlobalScope()) {
631 :       Node fnCaller = t.getScopeRoot();
632 :       Node fnCallerBody = fnCaller.getLastChild();
633 : 
634 :       // Don't allow any new vars into a scope that contains eval or one
635 :       // that contains functions (excluding the function being inlined).
636 :       Predicate<Node> match = new Predicate<Node>(){
637 :         @Override
638 :         public boolean apply(Node n) {
639 :           if (n.isName()) {
640 :             return n.getString().equals("eval");
641 :           }
642 :           if (!assumeMinimumCapture && n.isFunction()) {
643 :             return n != fnNode;
644 :           }
645 :           return false;
646 :         }
647 :       };
648 :       forbidTemps = NodeUtil.has(fnCallerBody,
649 :           match, NodeUtil.MATCH_NOT_FUNCTION);
650 :     }
651 : 
652 :     if (fnContainsVars && forbidTemps) {
653 :       return false;
654 :     }
655 : 
656 :     // If the caller contains functions or evals, verify we aren't adding any
657 :     // additional VAR declarations because aliasing is needed.
658 :     if (forbidTemps) {
659 :       Map<String, Node> args =
660 :           FunctionArgumentInjector.getFunctionCallParameterMap(
661 :               fnNode, callNode, this.safeNameIdSupplier);
662 :       boolean hasArgs = !args.isEmpty();
663 :       if (hasArgs) {
664 :         // Limit the inlining
665 :         Set<String> allNamesToAlias = Sets.newHashSet(namesToAlias);
666 :         FunctionArgumentInjector.maybeAddTempsForCallArguments(
667 :             fnNode, args, allNamesToAlias, compiler.getCodingConvention());
668 :         if (!allNamesToAlias.isEmpty()) {
669 :           return false;
670 :         }
671 :       }
672 :     }
673 : 
674 :     return true;
675 :   }"

" 64 :   Node mutate(String fnName, Node fnNode, Node callNode,
 65 :       String resultName, boolean needsDefaultResult, boolean isCallInLoop) {
 66 :     Node newFnNode = fnNode.cloneTree();
 67 :     // Now that parameter names have been replaced, make sure all the local
 68 :     // names are unique, to allow functions to be inlined multiple times
 69 :     // without causing conflicts.
 70 :     makeLocalNamesUnique(newFnNode, isCallInLoop);
 71 : 
 72 :     // Function declarations must be rewritten as function expressions as
 73 :     // they will be within a block and normalization prevents function
 74 :     // declarations within block as browser implementations vary.
 75 :     rewriteFunctionDeclarations(newFnNode.getLastChild());
 76 : 
 77 :     // TODO(johnlenz): Mark NAME nodes constant for parameters that are not
 78 :     // modified.
 79 :     Set<String> namesToAlias =
 80 :         FunctionArgumentInjector.findModifiedParameters(newFnNode);
 81 :     LinkedHashMap<String, Node> args =
 82 :         FunctionArgumentInjector.getFunctionCallParameterMap(
 83 :             newFnNode, callNode, this.safeNameIdSupplier);
 84 :     boolean hasArgs = !args.isEmpty();
 85 :     if (hasArgs) {
 86 :       FunctionArgumentInjector.maybeAddTempsForCallArguments(
 87 :           newFnNode, args, namesToAlias, compiler.getCodingConvention());
 88 :     }
 89 : 
 90 :     Node newBlock = NodeUtil.getFunctionBody(newFnNode);
 91 :     // Make the newBlock insertable .
 92 :     newBlock.detachFromParent();
 93 : 
 94 :     if (hasArgs) {
 95 :       Node inlineResult = aliasAndInlineArguments(newBlock,
 96 :           args, namesToAlias);
 97 :       Preconditions.checkState(newBlock == inlineResult);
 98 :     }
 99 : 
100 :     //
101 :     // For calls inlined into loops, VAR declarations are not reinitialized to
102 :     // undefined as they would have been if the function were called, so ensure
103 :     // that they are properly initialized.
104 :     //
105 :     if (isCallInLoop) {
106 :       fixUnitializedVarDeclarations(newBlock);
107 :     }
108 : 
109 :     String labelName = getLabelNameForFunction(fnName);
110 :     Node injectableBlock = replaceReturns(
111 :         newBlock, resultName, labelName, needsDefaultResult);
112 :     Preconditions.checkState(injectableBlock != null);
113 : 
114 :     return injectableBlock;
115 :   }"

"194 :   private static Set<String> findModifiedParameters(
195 :       Node n, Node parent, Set<String> names, Set<String> unsafe,
196 :       boolean inInnerFunction) {
197 :     Preconditions.checkArgument(unsafe != null);
198 :     if (n.isName()) {
199 :       if (names.contains(n.getString())) {
200 :         if (inInnerFunction || canNameValueChange(n, parent)) {
201 :           unsafe.add(n.getString());
202 :         }
203 :       }
204 :     } else if (n.isFunction()) {
205 :       // A function parameter can not be replaced with a direct inlined value
206 :       // if it is referred to by an inner function. The inner function
207 :       // can out live the call we are replacing, so inner function must
208 :       // capture a unique name.  This approach does not work within loop
209 :       // bodies so those are forbidden elsewhere.
210 :       inInnerFunction = true;
211 :     }
212 : 
213 :     for (Node c : n.children()) {
214 :       findModifiedParameters(c, n, names, unsafe, inInnerFunction);
215 :     }
216 : 
217 :     return unsafe;
218 :   }"

"231 :   private static boolean canNameValueChange(Node n, Node parent) {
232 :     int type = parent.getType();
233 :     return (type == Token.VAR || type == Token.INC || type == Token.DEC ||
234 :         (NodeUtil.isAssignmentOp(parent) && parent.getFirstChild() == n) ||
235 :         (NodeUtil.isForIn(parent)));
236 :   }"

